            $table->string('phone');
            $table->timestamps();
        });
    }

    public function down()
    {
        Schema::dropIfExists('card_phone');
    }
}
</CODE>

### Step 6: Run Migrations

Run the migration to create the database table.

```bash
php artisan migrate
```

